CURRENT_SHA256="400db829f8b5942d9ad4a43a1bbbc18d96fe2138964482146b8cd08fd63ea593"
PREDECESSOR_SHA256="b5bbcc3e74f769c94718de560fa476431d0b726997f48b9c4ad094a997d737b2"
def predecessor(raw):
    """Proof copy: reverse only reviewed Ctrip additions, preserving e30 query work."""
    if not isinstance(raw,bytes):
        raise ValueError("Ctrip scope source bytes required")
    actual=hashlib.sha256(raw).hexdigest()
    if actual==PREDECESSOR_SHA256:
        return raw
    if actual!=CURRENT_SHA256:
        raise ValueError("reviewed combined Ctrip/e30 comparator required")
    text=raw.decode("utf-8")
    for value in (BLOCK,CURRENT,REFERENCE):
        if text.count(value)!=1:
            raise RuntimeError("reviewed Ctrip region inverse boundary")
    restored=text.replace(BLOCK,"").replace(CURRENT,PRIOR).replace(REFERENCE,"").encode("utf-8")
    if hashlib.sha256(restored).hexdigest()!=PREDECESSOR_SHA256:
        raise RuntimeError("complete e30 comparator inverse")
    return restored
